import type { Role } from '@servicenow/sdk-core/app';
import type { Record } from '@servicenow/sdk-core/db';
/**
 * User access configuration for an AI Agent ACL (sys_security_acl).
 *
 * - `type: 'Any authenticated user'` — Any authenticated user can access. Optionally restrict further with roles.
 * - `type: 'Specific role'` — Only users with the specified roles can access. `roles` is required.
 * - `type: 'Public'` — No authentication required. Anyone can access.
 */
export type SecurityAclUserAccessConfig = Now.Internal.WithID<{
    /** Any authenticated user can access this agent */
    type: 'Any authenticated user';
}> | Now.Internal.WithID<{
    /** Only users with the specified roles can access this agent */
    type: 'Specific role';
    /** Required: at least one role must be specified */
    roles: (string | Role | Record<'sys_user_role'>)[];
}> | Now.Internal.WithID<{
    /** No authentication required — anyone can access this agent */
    type: 'Public';
}>;
